// Appends Haircoloring ids 382-404 and Texas TDLR ids 405-431
import { readFileSync, writeFileSync } from 'fs'
import { fileURLToPath } from 'url'
import { join, dirname } from 'path'

const __dirname = dirname(fileURLToPath(import.meta.url))
const FILE = join(__dirname, '../src/barber-questions.js')

function fmt(q, topic, topic_es) {
  return `  { id: ${q.id}, topic: ${topic}, topic_es: ${topic_es}, psi_topic: ${topic}, psi_topic_es: ${topic_es}, question: ${JSON.stringify(q.question)}, question_es: ${JSON.stringify(q.question_es)}, options: ${JSON.stringify(q.options)}, options_es: ${JSON.stringify(q.options_es)}, correct: ${q.correct}, explanation: ${JSON.stringify(q.explanation)} },`
}

// Last 23 Haircoloring (ids 382–404)
const hcT = `"Haircoloring"`, hcTes = `"Coloración del Cabello"`
const hcQ = [
  { id: 382, question: "A 'color refresher' or 'gloss' treatment is used to:", question_es: "Un tratamiento de 'refrescante de color' o 'gloss' se usa para:", options: ["Revive faded color between full color appointments by depositing a small amount of tone and adding shine", "Permanently change the hair color to a different level", "Remove previously applied color from the hair shaft", "Lift hair 1–2 levels before the main color application"], options_es: ["Revivir el color desvanecido entre citas de color completo depositando una pequeña cantidad de tono y añadiendo brillo", "Cambiar permanentemente el color del cabello a un nivel diferente", "Eliminar el color aplicado previamente del eje del cabello", "Levantar el cabello 1–2 niveles antes de la aplicación de color principal"], correct: 0, explanation: "Color glosses and refreshers are semi- or demi-permanent treatments that deposit tone, revive faded color, and add shine between full color appointments. They require no developer or use very low-volume developer and cause no lift." },
  { id: 383, question: "The process of artificially lightening hair by removing natural melanin is called:", question_es: "El proceso de aclarar artificialmente el cabello eliminando la melanina natural se llama:", options: ["Decolorization (bleaching)", "Toning", "Depositing", "Demipermanent processing"], options_es: ["Decoloración (aclarado)", "Tonificación", "Deposición", "Procesamiento demi-permanente"], correct: 0, explanation: "Decolorization (bleaching/lightening) removes the natural melanin from the hair cortex through an oxidation process. It does not add color — it removes pigment. Toning or coloring afterward deposits the desired shade on the decolorized hair." },
  { id: 384, question: "Which tool is used for precise, controlled hair color application in foil highlighting?", question_es: "¿Qué herramienta se usa para la aplicación precisa y controlada de color de cabello en el resaltado con papel de aluminio?", options: ["A tinting brush used to paint color or lightener onto specific sections before folding into foil", "An applicator bottle for root-to-end color flooding", "A wide-tooth comb to distribute color throughout large sections", "A spray bottle for even application throughout the hair"], options_es: ["Un cepillo de tinte usado para pintar color o aclarante en secciones específicas antes de doblar en papel de aluminio", "Una botella aplicadora para inundar el color de raíz a punta", "Un peine de dientes anchos para distribuir el color en secciones grandes", "Una botella de spray para aplicación uniforme en todo el cabello"], correct: 0, explanation: "A tinting brush (flat or fan-shaped) is used in foil highlight work to precisely paint color or lightener onto specific hair sections that are then folded into foil. Precision prevents color from contacting adjacent hair that should remain uncolored." },
  { id: 385, question: "An applicator bottle (squeeze bottle) is most appropriate for:", question_es: "Una botella aplicadora (botella exprimible) es más apropiada para:", options: ["Root retouch color applications, allowing the colorist to apply color along the parting lines precisely", "Freehand painting for balayage techniques", "Brush-on applications in foil highlights", "Toning applications on pre-lightened hair only"], options_es: ["Aplicaciones de color de retoque en la raíz, permitiendo al colorista aplicar color con precisión a lo largo de las líneas de separación", "Pintura a mano alzada para técnicas de balayage", "Aplicaciones con cepillo en resaltados con papel de aluminio", "Solo aplicaciones de tonificación en cabello pre-aclarado"], correct: 0, explanation: "Applicator bottles with pointed tips are ideal for root retouch applications, allowing the product to be applied precisely along part lines without over-saturating the surrounding hair. The fine tip provides control during the critical root-only application." },
  { id: 386, question: "Color 'oxidation' occurs when:", question_es: "La 'oxidación' del color ocurre cuando:", options: ["Oxygen from the developer reacts with the color molecules (dye intermediates) inside the hair shaft, developing them from small colorless molecules into large, colored pigment molecules", "Hair color is rinsed out with water, removing excess product", "The toner settles into the cuticle after lightening", "Body heat causes the color to fade after application"], options_es: ["El oxígeno del revelador reacciona con las moléculas de color (intermediarios del tinte) dentro del eje del cabello, desarrollándolos de moléculas pequeñas e incoloras en grandes moléculas de pigmento de color", "El color de cabello se enjuaga con agua, eliminando el exceso de producto", "El tónico se asienta en la cutícula después del aclarado", "El calor corporal hace que el color se desvanezca después de la aplicación"], correct: 0, explanation: "Color oxidation is the chemical reaction where hydrogen peroxide releases oxygen, which reacts with the small dye intermediate molecules inside the cortex. These small molecules couple together and oxidize into large, colored molecules too big to wash out." },
  { id: 387, question: "Haircoloring tools (bowls, brushes) should be cleaned immediately after use because:", question_es: "Las herramientas de coloración del cabello (tazones, cepillos) deben limpiarse inmediatamente después del uso porque:", options: ["Color oxidizes and hardens over time, making it much more difficult to remove if allowed to dry on the tools", "Color oxidation produces toxic fumes if left in the bowl", "TDLR requires immediate cleaning as part of chemical service regulations", "The bowl will be permanently stained by even temporary color products"], options_es: ["El color se oxida y se endurece con el tiempo, haciéndolo mucho más difícil de eliminar si se permite que se seque en las herramientas", "La oxidación del color produce gases tóxicos si se deja en el tazón", "TDLR requiere limpieza inmediata como parte de las regulaciones de servicios químicos", "El tazón quedará permanentemente manchado por incluso productos de color temporal"], correct: 0, explanation: "Mixed hair color continues to oxidize after the service. If left in bowls or on brushes, the oxidizing color hardens and becomes very difficult to clean. Immediate rinsing and cleaning prevents tool staining and degradation." },
  { id: 388, question: "A client's skin tone should be considered when recommending a hair color because:", question_es: "El tono de piel de un cliente debe considerarse al recomendar un color de cabello porque:", options: ["The contrast or harmony between hair color and skin undertone (warm vs cool) significantly affects how flattering the final result looks", "TDLR requires skin tone documentation for all color services", "Skin tone determines which developer volume is appropriate", "Certain colors are illegal to use on certain skin tones"], options_es: ["El contraste o armonía entre el color del cabello y el subtono de la piel (cálido vs frío) afecta significativamente lo favorecedor que se ve el resultado final", "TDLR requiere documentación del tono de piel para todos los servicios de color", "El tono de piel determina qué volumen de revelador es apropiado", "Ciertos colores son ilegales de usar en ciertos tonos de piel"], correct: 0, explanation: "Warm skin undertones (golden, peachy, yellow) are complemented by warm hair tones (gold, copper, warm brown). Cool skin undertones (pink, beige, blue) are complemented by cool hair tones (ash, platinum, cool brown). Skin tone analysis guides color recommendations." },
  { id: 389, question: "The term 'color banding' describes:", question_es: "El término 'bandas de color' describe:", options: ["Visible horizontal lines of different color depths or tones throughout the hair shaft, usually caused by overlapping color applications or uneven lightening", "A technique of creating striped highlights horizontally through the hair", "A color service for athletes using sport-themed color patterns", "Even color graduation from root to tip achieved with balayage"], options_es: ["Líneas horizontales visibles de diferentes profundidades o tonos de color a través del eje del cabello, generalmente causadas por aplicaciones de color superpuestas o aclarado desigual", "Una técnica de crear reflejos rayados horizontalmente a través del cabello", "Un servicio de color para atletas usando patrones de color temáticos de deportes", "Graduación uniforme de color de raíz a punta lograda con balayage"], correct: 0, explanation: "Color banding is a color correction problem characterized by visible lines of varying color depth — often darker at the regrowth, lighter at the midshaft, and faded at the ends (or vice versa) from repeated overlapping color applications." },
  { id: 390, question: "The purpose of a pre-color conditioning treatment (pre-treatment) is:", question_es: "El propósito de un tratamiento acondicionador pre-color (pre-tratamiento) es:", options: ["To equalize porosity and condition fragile hair before color application, helping achieve a more even color result", "To remove all color from the hair before starting fresh", "To open the cuticle wider for faster color processing", "To prevent any color from depositing on the ends"], options_es: ["Igualar la porosidad y acondicionar el cabello frágil antes de la aplicación del color, ayudando a lograr un resultado de color más uniforme", "Eliminar todo el color del cabello antes de comenzar de nuevo", "Abrir la cutícula más ampliamente para un procesamiento de color más rápido", "Evitar que cualquier color se deposite en las puntas"], correct: 0, explanation: "Pre-color treatments (fillers, equalizers) are applied to high-porosity areas (usually ends) before color to temporarily fill and equalize the cuticle. This reduces the rate of color absorption in those areas, achieving more even color distribution." },
  { id: 391, question: "Chemical 'color removers' (color reducers/strippers) work by:", question_es: "Los 'removedores de color' químicos (reductores/quitamanchas de color) funcionan mediante:", options: ["Reducing (shrinking) the oxidized artificial color molecules inside the cortex back to their original small size so they can be rinsed out, without bleaching the hair", "Bleaching the hair to remove both natural and artificial pigment", "Lifting the cuticle and physically scrubbing artificial pigment from the cortex", "Using acidic pH to dissolve color molecules from the hair shaft"], options_es: ["Reduciendo (encogiendo) las moléculas de color artificial oxidizadas dentro del córtex a su tamaño pequeño original para que puedan enjuagarse, sin blanquear el cabello", "Aclarando el cabello para eliminar tanto el pigmento natural como el artificial", "Levantando la cutícula y frotando físicamente el pigmento artificial del córtex", "Usando pH ácido para disolver las moléculas de color del eje del cabello"], correct: 0, explanation: "Color reducers (like sulfur-based removers) work by reversing the oxidation reaction — they reduce the large, locked-in color molecules back to their original small size so they can be rinsed out of the hair. They do not affect natural melanin or bleach the hair." },
  { id: 392, question: "After a haircoloring service, the client should be advised to use:", question_es: "Después de un servicio de coloración del cabello, se debe aconsejar al cliente que use:", options: ["Color-safe (sulfate-free) shampoo and conditioner to preserve color vibrancy and reduce fading", "Clarifying shampoo to remove excess color buildup from the scalp", "Any regular shampoo — color does not affect shampoo choice", "Dandruff shampoo to maintain scalp health after chemical color"], options_es: ["Champú y acondicionador seguros para el color (sin sulfatos) para preservar la viveza del color y reducir el desvanecimiento", "Champú clarificante para eliminar el exceso de acumulación de color del cuero cabelludo", "Cualquier champú regular — el color no afecta la elección del champú", "Champú anticaspa para mantener la salud del cuero cabelludo después del color químico"], correct: 0, explanation: "Color-safe (sulfate-free) shampoos are formulated to gently cleanse without stripping color molecules from the cortex. Sulfates (harsh detergents) open the cuticle aggressively and can cause rapid color fading. Using the right shampoo extends color longevity." },
  { id: 393, question: "Hydrogen peroxide in hair color developer is available in which percentages corresponding to volume strengths?", question_es: "El peróxido de hidrógeno en el revelador de color de cabello está disponible en qué porcentajes correspondientes a las resistencias de volumen?", options: ["3% (10 vol), 6% (20 vol), 9% (30 vol), 12% (40 vol)", "1% (10 vol), 3% (20 vol), 6% (30 vol), 9% (40 vol)", "5% (10 vol), 10% (20 vol), 15% (30 vol), 20% (40 vol)", "2% (10 vol), 4% (20 vol), 6% (30 vol), 8% (40 vol)"], options_es: ["3% (10 vol), 6% (20 vol), 9% (30 vol), 12% (40 vol)", "1% (10 vol), 3% (20 vol), 6% (30 vol), 9% (40 vol)", "5% (10 vol), 10% (20 vol), 15% (30 vol), 20% (40 vol)", "2% (10 vol), 4% (20 vol), 6% (30 vol), 8% (40 vol)"], correct: 0, explanation: "Developer hydrogen peroxide percentages: 10 volume = 3%, 20 volume = 6%, 30 volume = 9%, 40 volume = 12%. The 'volume' number refers to the volume of oxygen gas released per volume of solution during the oxidation reaction." },
  { id: 394, question: "A 'level system' describes hair color in terms of:", question_es: "Un 'sistema de niveles' describe el color de cabello en términos de:", options: ["Lightness or darkness (value) on a scale of 1–10, independent of tone — it describes HOW LIGHT or DARK the hair is", "The warmth or coolness (tone) of the hair color only", "The amount of red pigment present in the hair", "The hair's porosity and ability to accept color"], options_es: ["Claridad u oscuridad (valor) en una escala del 1 al 10, independientemente del tono — describe QUÉ TAN CLARO o OSCURO es el cabello", "Solo el calor o la frialdad (tono) del color del cabello", "La cantidad de pigmento rojo presente en el cabello", "La porosidad del cabello y su capacidad para aceptar el color"], correct: 0, explanation: "The level system measures lightness/darkness (value) on a numeric scale. Tone (warm, cool, neutral) describes the color's hue. A complete hair color description uses both: 'Level 7 Ash Blonde' (level = 7 / tone = ash). Level and tone together define the full color." },
  { id: 395, question: "A hair color formula for a permanent service is typically mixed immediately before application because:", question_es: "Una fórmula de color de cabello para un servicio permanente se mezcla típicamente justo antes de la aplicación porque:", options: ["Once mixed, hydrogen peroxide begins oxidizing the dye intermediates immediately — unused mixed color loses effectiveness and must be discarded after the service", "Mixed color improves with age and should be prepared 24 hours in advance", "Mixing in advance allows the ammonia to evaporate, reducing scalp irritation", "Pre-mixed color can be refrigerated and reused for up to one week"], options_es: ["Una vez mezclada, el peróxido de hidrógeno comienza a oxidar los intermediarios del tinte inmediatamente — el color mezclado no utilizado pierde efectividad y debe desecharse después del servicio", "El color mezclado mejora con el tiempo y debe prepararse 24 horas antes", "Mezclar con anticipación permite que el amoníaco se evapore, reduciendo la irritación del cuero cabelludo", "El color premezclado puede refrigerarse y reutilizarse hasta por una semana"], correct: 0, explanation: "Once color is mixed with developer, the oxidation process begins immediately. The effectiveness degrades with time. Mixed color should be used within the timeframe specified by the manufacturer (usually 30-60 minutes) and NEVER stored for reuse." },
  { id: 396, question: "Hair color should NOT be left to process beyond the recommended time because:", question_es: "El color de cabello NO debe dejarse procesar más allá del tiempo recomendado porque:", options: ["Over-processing can damage the hair structure and result in unwanted color shifts (color may become too dark, too dull, or the cortex may be weakened)", "Color stops processing exactly at the recommended time automatically", "Additional time always creates a lighter, more natural result", "Longer processing is safe and only beneficial for resistant gray coverage"], options_es: ["El sobreprocesamiento puede dañar la estructura del cabello y resultar en cambios de color no deseados (el color puede volverse demasiado oscuro, demasiado opaco, o el córtex puede debilitarse)", "El color deja de procesar exactamente a la hora recomendada automáticamente", "El tiempo adicional siempre crea un resultado más claro y más natural", "El procesamiento más largo es seguro y solo beneficioso para la cobertura de canas resistentes"], correct: 0, explanation: "Over-processing permanent color damages the hair's protein structure and can cause the color to shift (deepen, go flat, or pull unwanted tones). Hair integrity and accurate timing are both critical for optimal color results." },
  { id: 397, question: "When two or more colors are 'mixed on the wheel' (complementary colors blended), the result is:", question_es: "Cuando dos o más colores se 'mezclan en la rueda' (colores complementarios mezclados), el resultado es:", options: ["Neutralization — the colors cancel each other out producing a neutral (brown/gray) tone", "A brighter, more saturated version of both colors", "A new primary color", "A transparent, clear result with no color remaining"], options_es: ["Neutralización — los colores se cancelan mutuamente produciendo un tono neutral (marrón/gris)", "Una versión más brillante y saturada de ambos colores", "Un nuevo color primario", "Un resultado transparente y claro sin color restante"], correct: 0, explanation: "Mixing complementary colors (opposite on the wheel: red+green, blue+orange, yellow+violet) produces a neutral, muddy brown or gray because each color absorbs the wavelengths the other reflects. This is used to cancel unwanted tones in color correction." },
  { id: 398, question: "Hair that has been chemically colored is more susceptible to sun damage because:", question_es: "El cabello que ha sido coloreado químicamente es más susceptible al daño solar porque:", options: ["Chemical processing opens and raises the cuticle, making the cortex more exposed to UV radiation which can fade color and further damage the cortex", "Chemical color makes hair thicker and more absorbent of UV radiation", "Artificial color molecules attract UV rays at a higher rate than natural melanin", "Sunlight neutralizes the oxidation of color molecules, reversing the color service"], options_es: ["El procesamiento químico abre y levanta la cutícula, haciendo el córtex más expuesto a la radiación UV que puede desvanecer el color y dañar aún más el córtex", "El color químico hace el cabello más grueso y más absorbente de la radiación UV", "Las moléculas de color artificial atraen los rayos UV a una tasa más alta que la melanina natural", "La luz solar neutraliza la oxidación de las moléculas de color, revirtiendo el servicio de color"], correct: 0, explanation: "Chemical processing (color, bleach, perm) disrupts the cuticle. A compromised cuticle provides less protection to the cortex from UV radiation. UV rays fade artificial color and cause further protein damage. UV-protective hair products and heat protectants are recommended." },
  { id: 399, question: "When selecting a hair color formula for a client, the barber/colorist must determine:", question_es: "Al seleccionar una fórmula de color de cabello para un cliente, el barbero/colorista debe determinar:", options: ["The client's current level, desired level, natural tone/undertone, any existing artificial color, and the percentage of gray to be covered", "Only the client's desired color shade from a color chart", "The client's age and hair length only", "The brand of shampoo the client currently uses"], options_es: ["El nivel actual del cliente, el nivel deseado, el tono/subtono natural, cualquier color artificial existente y el porcentaje de canas a cubrir", "Solo el tono de color deseado del cliente de una carta de colores", "Solo la edad y la longitud del cabello del cliente", "La marca de champú que el cliente actualmente usa"], correct: 0, explanation: "Complete color assessment includes: current natural level, desired target level, existing artificial color (history), percentage of gray (for coverage formulation), natural undertone, and hair condition. All these factors determine the correct formula, developer, and application method." },
  { id: 400, question: "The term 'tonality' or 'tone' in hair color refers to:", question_es: "El término 'tonalidad' o 'tono' en el color de cabello se refiere a:", options: ["The warm, cool, or neutral quality (hue) of the hair color — such as gold, ash, copper, red, or violet — independent of how light or dark the color is", "How long a color lasts before fading", "The number on the level scale from 1 to 10", "The pH of the color formula"], options_es: ["La calidad cálida, fría o neutral (matiz) del color del cabello — como dorado, ceniza, cobre, rojo o violeta — independientemente de qué tan claro u oscuro es el color", "Cuánto dura un color antes de desvanecerse", "El número en la escala de niveles del 1 al 10", "El pH de la fórmula de color"], correct: 0, explanation: "Tone (tonality) describes the hue (the underlying color quality: warm, cool, neutral) of the hair color, separate from its level (lightness/darkness). Two colors can be the same level but different tones (e.g., Level 7 Gold vs Level 7 Ash)." },
  { id: 401, question: "The 'international color code' system for professional hair colors uses numbers after a slash (/) or a decimal point to indicate:", question_es: "El sistema de 'código de color internacional' para colores de cabello profesionales usa números después de una barra (/) o un punto decimal para indicar:", options: ["The tone or tonal family of the color (e.g., .0=natural, .1=ash, .3=gold, .4=copper, .6=red, .7=mahogany)", "The volume of developer to mix with the color", "The processing time in minutes", "The percentage of gray the formula can cover"], options_es: ["El tono o familia tonal del color (p. ej., .0=natural, .1=ceniza, .3=dorado, .4=cobre, .6=rojo, .7=caoba)", "El volumen del revelador para mezclar con el color", "El tiempo de procesamiento en minutos", "El porcentaje de canas que la fórmula puede cubrir"], correct: 0, explanation: "The international numbering system uses a first number for the level (1-10) and numbers after the slash or decimal for the tone. For example, 7.3 = Level 7 (medium blonde) + .3 (golden tone). This system is used across many professional brands." },
  { id: 402, question: "The best time to evaluate the results of a haircoloring service is:", question_es: "El mejor momento para evaluar los resultados de un servicio de coloración del cabello es:", options: ["After rinsing, neutralizing, drying, and styling — the true final color is only accurately visible on dry, styled hair", "Immediately after removing color from the scalp during processing", "While the color is still processing on the head", "At the next appointment two weeks later"], options_es: ["Después de enjuagar, neutralizar, secar y peinar — el verdadero color final solo es visible con precisión en el cabello seco y peinado", "Inmediatamente después de eliminar el color del cuero cabelludo durante el procesamiento", "Mientras el color aún está procesando en la cabeza", "En la próxima cita dos semanas después"], correct: 0, explanation: "Color results cannot be accurately assessed on wet hair — wet hair appears darker and can shift as it dries. The true final color is evaluated after the hair is fully dried and styled. Always check results under natural or salon lighting." },
  { id: 403, question: "A client requests 'highlights' with warm golden tones. Which color family should be selected for the highlight formula?", question_es: "Un cliente solicita 'reflejos' con tonos dorados cálidos. ¿Qué familia de colores debe seleccionarse para la fórmula de reflejos?", options: ["Warm tones: gold, copper, or honey-based color families", "Cool tones: ash or violet-based color families", "Neutral tones: natural/green-based families for no warmth", "Red-violet tones to contrast with the base hair color"], options_es: ["Tonos cálidos: familias de colores dorado, cobre o miel", "Tonos fríos: familias de colores ceniza o violeta", "Tonos neutros: familias naturales/verde para sin calidez", "Tonos rojo-violeta para contrastar con el color base del cabello"], correct: 0, explanation: "Warm golden tones fall within the gold (.3), honey (.32), and copper (.4) tone families. Ash and violet families would produce cool, non-golden results. Color tone selection must align with the client's desired final appearance." },
  { id: 404, question: "A haircoloring record card must include which critical information to protect both the professional and client?", question_es: "Una tarjeta de registro de coloración del cabello debe incluir qué información crítica para proteger tanto al profesional como al cliente?", options: ["Patch test results, color formula used, developer volume, processing time, application method, final result, and any adverse reactions", "Only the brand name of the color used and the final result", "The client's payment information and appointment date only", "The barber's license number and TDLR inspection date"], options_es: ["Resultados de la prueba de parche, fórmula de color usada, volumen del revelador, tiempo de procesamiento, método de aplicación, resultado final y cualquier reacción adversa", "Solo el nombre de la marca del color usado y el resultado final", "Solo la información de pago del cliente y la fecha de la cita", "El número de licencia del barbero y la fecha de inspección de TDLR"], correct: 0, explanation: "A complete color record includes: patch test results/date, formula used (brand, number, tones), developer volume, mixing ratio, processing time, application method, final result, and any reactions. This documentation is legally protective and enables consistent future service." },
]

// First 27 Texas TDLR Laws & Regulations (ids 405–431)
const tdT = `"Texas TDLR Laws & Regulations"`, tdTes = `"Leyes y Regulaciones de Texas TDLR"`
const tdQ = [
  { id: 405, question: "Which Texas state agency regulates barbering and issues barber licenses in Texas?", question_es: "¿Qué agencia estatal de Texas regula la barbería y emite licencias de barbero en Texas?", options: ["Texas Department of Licensing and Regulation (TDLR)", "Texas State Board of Cosmetology", "Texas Department of Health Services", "Texas Education Agency"], options_es: ["Departamento de Licencias y Regulación de Texas (TDLR)", "Junta Estatal de Cosmetología de Texas", "Departamento de Servicios de Salud de Texas", "Agencia de Educación de Texas"], correct: 0, explanation: "The Texas Department of Licensing and Regulation (TDLR) is the state agency that licenses, regulates, and enforces barbering rules in Texas. TDLR absorbed the former Texas Barbering Board functions." },
  { id: 406, question: "Texas barbering statutes are found primarily in:", question_es: "Los estatutos de barbería de Texas se encuentran principalmente en:", options: ["Texas Occupations Code, Chapter 1601 (Barbering)", "Texas Occupations Code, Chapter 1603 (Cosmetology)", "Texas Health and Safety Code, Chapter 147", "Texas Administrative Code, Title 25"], options_es: ["Código de Ocupaciones de Texas, Capítulo 1601 (Barbería)", "Código de Ocupaciones de Texas, Capítulo 1603 (Cosmetología)", "Código de Salud y Seguridad de Texas, Capítulo 147", "Código Administrativo de Texas, Título 25"], correct: 0, explanation: "Barbering law in Texas is primarily found in Texas Occupations Code Chapter 1601. The administrative rules implementing that statute are in Texas Administrative Code Title 16, Chapter 82." },
  { id: 407, question: "Texas Administrative Code rules for barbershops are found in:", question_es: "Las reglas del Código Administrativo de Texas para barberías se encuentran en:", options: ["Title 16, Chapter 82 (Barbering)", "Title 16, Chapter 83 (Cosmetology)", "Title 25, Chapter 135 (Barbershops)", "Title 37, Chapter 14 (Licensing)"], options_es: ["Título 16, Capítulo 82 (Barbería)", "Título 16, Capítulo 83 (Cosmetología)", "Título 25, Capítulo 135 (Barberías)", "Título 37, Capítulo 14 (Licencias)"], correct: 0, explanation: "Texas barbershop regulations are in Texas Administrative Code Title 16, Chapter 82. Chapter 83 governs cosmetology. These administrative rules contain the detailed sanitation, safety, and operational requirements for barbershops." },
  { id: 408, question: "To obtain a Class A Barber license in Texas, an applicant must complete:", question_es: "Para obtener una licencia de Barbero Clase A en Texas, un solicitante debe completar:", options: ["At least 1,500 hours of approved barber education at a licensed barber school", "500 hours at a barbershop under an apprentice permit", "2,000 hours at a licensed school or equivalent apprenticeship", "1,000 hours of barber school plus 1,000 hours of on-the-job training"], options_es: ["Al menos 1,500 horas de educación de barbería aprobada en una escuela de barbería con licencia", "500 horas en una barbería bajo un permiso de aprendiz", "2,000 horas en una escuela con licencia o aprendizaje equivalente", "1,000 horas de escuela de barbería más 1,000 horas de capacitación en el trabajo"], correct: 0, explanation: "Texas requires a minimum of 1,500 hours of barber education at a TDLR-licensed barber school to qualify for the Class A Barber license examination." },
  { id: 409, question: "After completing the required education hours, a barber student must pass which examinations to obtain a Texas Class A Barber license?", question_es: "Después de completar las horas de educación requeridas, un estudiante de barbería debe pasar qué exámenes para obtener una licencia de Barbero Clase A de Texas?", options: ["Both a written (theory) examination and a practical (skills) examination administered by PSI Exams on behalf of TDLR", "Only a written examination at a TDLR office", "Only a practical examination at the barber school", "A written examination by TDLR and a portfolio review"], options_es: ["Tanto un examen escrito (teórico) como un examen práctico (habilidades) administrado por PSI Exams en nombre de TDLR", "Solo un examen escrito en una oficina de TDLR", "Solo un examen práctico en la escuela de barbería", "Un examen escrito de TDLR y una revisión de portafolio"], correct: 0, explanation: "Texas barber applicants must pass both a written theory exam and a practical skills exam, both administered by PSI Exams under contract with TDLR. Both exams must be passed before the license is issued." },
  { id: 410, question: "The minimum age requirement to obtain a Texas barber license is:", question_es: "El requisito de edad mínima para obtener una licencia de barbero de Texas es:", options: ["17 years old (or 16 with consent and agreement to complete requirements)", "18 years old", "21 years old", "There is no minimum age requirement"], options_es: ["17 años (o 16 con consentimiento y acuerdo para completar los requisitos)", "18 años", "21 años", "No hay requisito de edad mínima"], correct: 0, explanation: "Texas allows students to begin barber school at 16 years of age with appropriate consent. The minimum age to obtain a barber license is 17 years old. Check current TDLR rules as requirements may be updated." },
  { id: 411, question: "A Texas Class A Barber license must be renewed:", question_es: "Una licencia de Barbero Clase A de Texas debe renovarse:", options: ["Every two years (biennially), with the expiration date printed on the license", "Every year", "Every five years", "Only when changing employers or barbershop locations"], options_es: ["Cada dos años (bienalmente), con la fecha de vencimiento impresa en la licencia", "Cada año", "Cada cinco años", "Solo al cambiar de empleador o ubicación de barbería"], correct: 0, explanation: "Texas barber licenses are renewed on a biennial (every two years) basis. The license expiration date is printed on the license. Barbers must renew before expiration to continue practicing legally." },
  { id: 412, question: "To renew a Texas barber license, the barber must complete:", question_es: "Para renovar una licencia de barbero de Texas, el barbero debe completar:", options: ["6 hours of continuing education (CE) approved by TDLR during each renewal period", "12 hours of CE every year", "No continuing education is required for barbers in Texas", "2 hours of CE per year (4 hours for the two-year period)"], options_es: ["6 horas de educación continua (EC) aprobada por TDLR durante cada período de renovación", "12 horas de EC cada año", "No se requiere educación continua para los barberos en Texas", "2 horas de EC por año (4 horas para el período de dos años)"], correct: 0, explanation: "Texas barbers must complete 6 hours of TDLR-approved continuing education (CE) per two-year renewal period. CE topics may include sanitation, safety, and other areas specified by TDLR. Always verify current requirements as they may change." },
  { id: 413, question: "Which of the following is included in the scope of practice for a Texas Class A Barber?", question_es: "¿Cuál de los siguientes está incluido en el alcance de práctica de un Barbero Clase A de Texas?", options: ["Cutting, trimming, and styling hair; shaving the face and neck; performing beard and mustache design; and shampooing the hair", "Performing chemical facial treatments and facials beyond the beard area", "Providing scalp injections or medical-grade treatments", "Performing eyelash extensions and eyebrow threading"], options_es: ["Cortar, recortar y peinar el cabello; afeitar el rostro y el cuello; realizar diseño de barba y bigote; y lavar el cabello con champú", "Realizar tratamientos faciales químicos y faciales más allá del área de la barba", "Proporcionar inyecciones en el cuero cabelludo o tratamientos de grado médico", "Realizar extensiones de pestañas y depilación de cejas con hilo"], correct: 0, explanation: "A Texas Class A Barber is licensed to cut, trim, clip, and style hair; shave the face and neck; design beards and mustaches; shampoo hair; and apply some chemical services. Scope of practice is limited to these activities as defined by Texas Occupations Code Chapter 1601." },
  { id: 414, question: "A Texas barbershop must obtain which type of license from TDLR before opening?", question_es: "Una barbería de Texas debe obtener qué tipo de licencia de TDLR antes de abrir?", options: ["A barbershop establishment license (barbershop permit)", "A Class A Barber license for each barber who will work there", "A business license from the Texas Secretary of State only", "An annual health permit from the local city government"], options_es: ["Una licencia de establecimiento de barbería (permiso de barbería)", "Una licencia de Barbero Clase A para cada barbero que trabajará allí", "Solo una licencia comercial del Secretario de Estado de Texas", "Un permiso de salud anual del gobierno local de la ciudad"], correct: 0, explanation: "In addition to the individual barber licenses, the physical barbershop location must hold a TDLR barbershop establishment license. Both the individual barber licenses and the establishment license must be current and displayed." },
  { id: 415, question: "TDLR barbershop inspections in Texas:", question_es: "Las inspecciones de barberías de TDLR en Texas:", options: ["May occur at any time during business hours without prior notice to ensure compliance with sanitation and safety standards", "Are announced 30 days in advance by certified mail", "Only occur annually on a fixed scheduled date", "Are triggered only by a formal complaint"], options_es: ["Pueden ocurrir en cualquier momento durante las horas de negocio sin previo aviso para garantizar el cumplimiento de los estándares de saneamiento y seguridad", "Se anuncian con 30 días de anticipación por correo certificado", "Solo ocurren anualmente en una fecha fija programada", "Son desencadenadas solo por una queja formal"], correct: 0, explanation: "TDLR inspectors may visit any licensed barbershop during business hours without prior notice to check compliance with Texas barbering sanitation rules, license display requirements, and safety standards." },
  { id: 416, question: "A Texas barber's license and the barbershop license must be displayed:", question_es: "La licencia de barbero de Texas y la licencia de barbería deben exhibirse:", options: ["In a conspicuous location visible to clients within the barbershop", "Only in the owner's back office or filing cabinet", "On the barber's person at all times during work", "Only when requested by a TDLR inspector"], options_es: ["En un lugar visible para los clientes dentro de la barbería", "Solo en la oficina trasera del propietario o en un archivador", "En la persona del barbero en todo momento durante el trabajo", "Solo cuando lo solicita un inspector de TDLR"], correct: 0, explanation: "Texas law requires that all barber licenses and the barbershop establishment license be displayed in a conspicuous (clearly visible) location within the barbershop, accessible for client and inspector viewing." },
  { id: 417, question: "Under Texas law, a booth renter (independent contractor) in a barbershop:", question_es: "Según la ley de Texas, un arrendatario de espacio (contratista independiente) en una barbería:", options: ["Must hold their own valid Class A Barber license and comply with all sanitation rules independently", "Does not need a separate license — the shop owner's license covers booth renters", "Only needs a TDLR apprentice permit to operate as a booth renter", "Must be employed by the shop owner, not operate independently"], options_es: ["Debe tener su propia licencia válida de Barbero Clase A y cumplir con todas las reglas de saneamiento de forma independiente", "No necesita una licencia separada — la licencia del dueño de la barbería cubre a los arrendatarios de espacio", "Solo necesita un permiso de aprendiz de TDLR para operar como arrendatario de espacio", "Debe ser empleado del dueño de la barbería, no operar de forma independiente"], correct: 0, explanation: "Each individual barber — whether an employee or a booth renter — must hold their own valid Class A Barber license. Booth renters are independent contractors who rent space from the shop owner and are responsible for maintaining their own license and compliance." },
  { id: 418, question: "What is the role of the Texas Occupations Code Chapter 1601 in the barbering industry?", question_es: "¿Cuál es el papel del Capítulo 1601 del Código de Ocupaciones de Texas en la industria de la barbería?", options: ["It is the primary statute that establishes the legal framework for barbering licensing, education, scope of practice, and enforcement in Texas", "It regulates only the education curriculum for barber schools", "It sets tax rates for barbershop income in Texas", "It controls the prices barbers may charge for their services"], options_es: ["Es el estatuto primario que establece el marco legal para la licencia de barbería, la educación, el alcance de la práctica y la aplicación en Texas", "Regula solo el plan de estudios de educación para las escuelas de barbería", "Establece las tasas de impuestos para los ingresos de las barberías en Texas", "Controla los precios que los barberos pueden cobrar por sus servicios"], correct: 0, explanation: "Texas Occupations Code Chapter 1601 is the primary law governing barbering in Texas. It establishes who must be licensed, what education is required, what constitutes the scope of practice, penalties for violations, and the authority of TDLR to regulate the industry." },
  { id: 419, question: "A Texas barber who performs services without a valid, current license is subject to:", question_es: "Un barbero de Texas que realiza servicios sin una licencia válida y vigente está sujeto a:", options: ["Administrative penalties from TDLR, including fines and potential prohibition from obtaining a license", "Only a verbal warning for a first offense", "Criminal prosecution under federal law", "Revocation of the barbershop's business license only"], options_es: ["Penalidades administrativas de TDLR, incluyendo multas y posible prohibición de obtener una licencia", "Solo una advertencia verbal por una primera infracción", "Enjuiciamiento penal bajo la ley federal", "Solo la revocación de la licencia comercial de la barbería"], correct: 0, explanation: "Practicing barbering without a valid Texas license is a violation of the Occupations Code. TDLR can impose administrative penalties (fines), cease-and-desist orders, and deny future license applications. Violations can also result in state criminal charges." },
  { id: 420, question: "A Texas barber who changes their name or mailing address must:", question_es: "Un barbero de Texas que cambia su nombre o dirección postal debe:", options: ["Notify TDLR within 30 days of the change and update their license information", "Wait until the next renewal period to update their information", "Contact the barbershop owner who will notify TDLR on their behalf", "File a court order before TDLR will accept the change"], options_es: ["Notificar a TDLR dentro de los 30 días del cambio y actualizar la información de su licencia", "Esperar hasta el próximo período de renovación para actualizar su información", "Contactar al dueño de la barbería quien notificará a TDLR en su nombre", "Presentar una orden judicial antes de que TDLR acepte el cambio"], correct: 0, explanation: "TDLR requires barbers to update their contact and license information within 30 days of any change (name, address). This ensures TDLR can contact the licensee regarding renewals, inspections, and compliance matters." },
  { id: 421, question: "An 'apprentice permit' in Texas barbering allows the holder to:", question_es: "Un 'permiso de aprendiz' en la barbería de Texas permite al titular:", options: ["Practice barbering under the direct supervision of a licensed Class A Barber while accumulating the required hours toward full licensure", "Practice barbering independently without supervision", "Own and operate a barbershop", "Teach barbering at a licensed school"], options_es: ["Practicar la barbería bajo la supervisión directa de un Barbero Clase A con licencia mientras acumula las horas requeridas hacia la licencia completa", "Practicar la barbería de forma independiente sin supervisión", "Poseer y operar una barbería", "Enseñar barbería en una escuela con licencia"], correct: 0, explanation: "An apprentice permit allows a person learning barbering to practice under direct supervision of a licensed Class A Barber in an approved establishment. The apprentice must be supervised and cannot practice independently." },
  { id: 422, question: "Which of the following actions would constitute 'unprofessional conduct' under Texas barber law?", question_es: "¿Cuál de las siguientes acciones constituiría 'conducta no profesional' según la ley de barbería de Texas?", options: ["Practicing while impaired by alcohol or drugs, or performing services in an unsanitary manner that risks client health", "Charging below-market rates for services", "Working without an appointment book", "Using generic professional products instead of name brands"], options_es: ["Practicar mientras está bajo la influencia del alcohol o las drogas, o realizar servicios de manera no higiénica que ponga en riesgo la salud del cliente", "Cobrar precios por debajo del mercado por servicios", "Trabajar sin un libro de citas", "Usar productos profesionales genéricos en lugar de marcas reconocidas"], correct: 0, explanation: "Unprofessional conduct under Texas barber law includes practicing while impaired, performing unsanitary services, fraud, deception, and other conduct that harms or endangers clients. TDLR can revoke or suspend a license for unprofessional conduct." },
  { id: 423, question: "A Texas barber with a criminal conviction must:", question_es: "Un barbero de Texas con una condena criminal debe:", options: ["Disclose the conviction on the license application; TDLR reviews convictions on a case-by-case basis to determine if they are disqualifying", "Automatically be denied a barber license regardless of the crime", "Only disclose felony convictions, not misdemeanors", "Wait 10 years after the conviction before applying for a license"], options_es: ["Divulgar la condena en la solicitud de licencia; TDLR revisa las condenas caso por caso para determinar si son descalificantes", "Automáticamente ser denegado una licencia de barbero independientemente del crimen", "Solo divulgar condenas por delitos graves, no por delitos menores", "Esperar 10 años después de la condena antes de solicitar una licencia"], correct: 0, explanation: "Texas uses a case-by-case review process for criminal convictions. TDLR evaluates the nature and severity of the crime, its relevance to barbering, and the time elapsed since conviction. Not all convictions automatically disqualify an applicant." },
  { id: 424, question: "Advertising for a Texas barbershop must:", question_es: "La publicidad de una barbería de Texas debe:", options: ["Be truthful and not contain false or misleading claims about services, qualifications, or prices", "Always include the TDLR license number in every advertisement", "Be approved by TDLR before publication", "Include the number of licensed barbers working at the location"], options_es: ["Ser veraz y no contener afirmaciones falsas o engañosas sobre servicios, calificaciones o precios", "Siempre incluir el número de licencia de TDLR en cada anuncio", "Ser aprobada por TDLR antes de la publicación", "Incluir el número de barberos con licencia que trabajan en la ubicación"], correct: 0, explanation: "All advertising by licensed barbershops must be truthful and not misleading. False advertising (claiming credentials not held, services not offered, prices not honored) is a violation of Texas law and TDLR rules." },
  { id: 425, question: "A Texas barber wishing to work in another state may be able to obtain a license through:", question_es: "Un barbero de Texas que desee trabajar en otro estado puede obtener una licencia a través de:", options: ["License reciprocity or endorsement agreements between states — the other state recognizes Texas credentials", "Simply presenting their Texas license at the other state's barbershop", "Applying for a 'national barber license' through the federal government", "Re-taking only the practical exam in the new state"], options_es: ["Acuerdos de reciprocidad o reconocimiento de licencias entre estados — el otro estado reconoce las credenciales de Texas", "Simplemente presentar su licencia de Texas en la barbería del otro estado", "Solicitar una 'licencia nacional de barbero' a través del gobierno federal", "Solo volver a tomar el examen práctico en el nuevo estado"], correct: 0, explanation: "Many states have reciprocity or endorsement agreements that allow licensed barbers from another state to obtain a license without completing the full education requirements again — if the other state's requirements are substantially equivalent." },
  { id: 426, question: "A barbershop license is issued to:", question_es: "Una licencia de barbería se emite a:", options: ["The owner of the barbershop establishment (business entity or individual) for the specific physical location", "Each barber employed at the shop", "The building owner where the barbershop is located", "The Texas Secretary of State"], options_es: ["El propietario del establecimiento de barbería (entidad comercial o individuo) para la ubicación física específica", "Cada barbero empleado en la barbería", "El propietario del edificio donde se encuentra la barbería", "El Secretario de Estado de Texas"], correct: 0, explanation: "A barbershop establishment license is issued to the owner of the business for the specific physical location. The license covers the business as an entity — it is separate from the individual barber licenses required for each practitioner." },
  { id: 427, question: "If a TDLR inspector finds a barbershop in violation of sanitation requirements, TDLR may:", question_es: "Si un inspector de TDLR encuentra una barbería en violación de los requisitos de saneamiento, TDLR puede:", options: ["Issue a notice of violation, require corrective action, impose administrative fines, and in serious cases, close the barbershop", "Only warn the shop owner verbally", "Issue a criminal warrant for the barber's arrest", "Transfer the barbershop license to another owner"], options_es: ["Emitir un aviso de violación, requerir acción correctiva, imponer multas administrativas y, en casos graves, cerrar la barbería", "Solo advertir verbalmente al dueño de la barbería", "Emitir una orden de arresto criminal para el barbero", "Transferir la licencia de la barbería a otro propietario"], correct: 0, explanation: "TDLR has administrative enforcement authority. Upon finding violations, they can issue notices of violation, require corrective actions within a set timeframe, impose fines, and in serious cases (imminent health risk), temporarily close the establishment." },
  { id: 428, question: "A Texas barber is prohibited from performing services on a client who is:", question_es: "A un barbero de Texas se le prohíbe realizar servicios en un cliente que:", options: ["Visibly intoxicated, has a contagious skin condition in the service area, or has open wounds that could expose either party to harm", "Under 18 years of age without parental consent", "Unable to speak English fluently", "A first-time client who has not completed a waiver form"], options_es: ["Visiblemente intoxicado, tiene una condición cutánea contagiosa en el área de servicio o tiene heridas abiertas que podrían exponer a cualquiera de las partes a daño", "Menor de 18 años sin consentimiento de los padres", "Incapaz de hablar inglés con fluidez", "Un cliente por primera vez que no ha completado un formulario de exención"], correct: 0, explanation: "Barbers must refuse service in specific situations: visibly intoxicated clients (safety risk), clients with contagious conditions in the service area (infection risk), and clients with open wounds that pose a risk of harm or exposure to both parties." },
  { id: 429, question: "The PSI written examination for a Texas Class A Barber license covers which subject areas?", question_es: "El examen escrito de PSI para una licencia de Barbero Clase A de Texas cubre qué áreas temáticas?", options: ["Infection Control & Sanitation, Haircutting & Hair Styling, Chemical Waving & Relaxing, Haircoloring, Texas TDLR Laws & Regulations, Shampooing & Conditioning, and Nail Care & Skin Care", "Only practical skills such as cutting, shaving, and styling", "Texas history and business law only", "Anatomy and physiology courses equivalent to a medical license"], options_es: ["Control de Infecciones y Saneamiento, Corte de Cabello y Peinado, Ondulación Química y Alisado, Coloración del Cabello, Leyes y Regulaciones de Texas TDLR, Champú y Acondicionamiento, y Cuidado de Uñas y Piel", "Solo habilidades prácticas como cortar, afeitar y peinar", "Solo historia de Texas y derecho comercial", "Cursos de anatomía y fisiología equivalentes a una licencia médica"], correct: 0, explanation: "The PSI Texas Class A Barber written exam covers seven content areas: Infection Control & Sanitation, Haircutting & Hair Styling, Chemical Waving & Relaxing, Haircoloring, Texas TDLR Laws & Regulations, Shampooing & Conditioning, and Nail Care & Skin Care." },
  { id: 430, question: "A Texas barber's license becomes 'inactive' when:", question_es: "La licencia de un barbero de Texas se vuelve 'inactiva' cuando:", options: ["The barber requests inactive status (to stop practicing temporarily) — the license is maintained but the barber cannot perform services until reactivating", "The license has not been renewed and has lapsed beyond the grace period", "The barber moves to another state permanently", "The barber's employer reports them to TDLR"], options_es: ["El barbero solicita estado inactivo (para dejar de practicar temporalmente) — la licencia se mantiene pero el barbero no puede realizar servicios hasta reactivarla", "La licencia no ha sido renovada y ha vencido más allá del período de gracia", "El barbero se muda a otro estado permanentemente", "El empleador del barbero lo reporta a TDLR"], correct: 0, explanation: "A barber may voluntarily request inactive status from TDLR if they wish to temporarily stop practicing (e.g., for extended leave). An inactive licensee cannot perform services. To practice again, they must reactivate the license and meet all current requirements." },
  { id: 431, question: "Which Texas TDLR rule governs the minimum sanitation practices required in a barbershop?", question_es: "¿Qué regla de TDLR de Texas rige las prácticas mínimas de saneamiento requeridas en una barbería?", options: ["Texas Administrative Code Title 16, Chapter 82 (Barbering — Sanitation Standards)", "Texas Health and Safety Code Chapter 341 (Water Quality)", "Texas Occupations Code Chapter 1601 (Barbering Licensing only)", "City health codes supersede state rules for sanitation"], options_es: ["Código Administrativo de Texas Título 16, Capítulo 82 (Barbería — Estándares de Saneamiento)", "Código de Salud y Seguridad de Texas Capítulo 341 (Calidad del Agua)", "Código de Ocupaciones de Texas Capítulo 1601 (Solo Licencias de Barbería)", "Los códigos de salud de la ciudad reemplazn las reglas estatales para el saneamiento"], correct: 0, explanation: "Barbershop sanitation standards are established in Texas Administrative Code Title 16, Chapter 82. These rules specify implement disinfection, facility cleanliness, waste disposal, and other sanitation requirements that must be met by all licensed barbershops." },
]

let out = readFileSync(FILE, 'utf8')
out += hcQ.map(q => fmt(q, hcT, hcTes)).join('\n') + '\n'
out += '\n// ─── TEXAS TDLR LAWS & REGULATIONS (ids 405–451) ────────────────────────────\n'
out += tdQ.map(q => fmt(q, tdT, tdTes)).join('\n') + '\n'
writeFileSync(FILE, out, 'utf8')
console.log(`Appended ${hcQ.length} Haircoloring (ids ${hcQ[0].id}–${hcQ[hcQ.length-1].id}) + ${tdQ.length} TDLR (ids ${tdQ[0].id}–${tdQ[tdQ.length-1].id})`)
